/**
 * Main JavaScript file for the Hello World Web App.
 * Contains Alpine.js components and global state management.
 *
 * @fileoverview Alpine.js components for login and welcome pages.
 * @author Senior JavaScript Engineer
 * @version 1.0.0
 */

// Alpine.js store for global authentication state
document.addEventListener('alpine:init', () => {
  Alpine.store('auth', {
    /** @type {boolean} Indicates if the user is authenticated */
    isAuthenticated: localStorage.getItem('isAuthenticated') === 'true',

    /** @type {string|null} Authentication token */
    token: localStorage.getItem('authToken'),

    /** @type {Object|null} User information */
    user: JSON.parse(localStorage.getItem('user') || 'null'),

    /**
     * Sets the authentication state
     * @param {boolean} status - Authentication status
     * @param {string|null} token - Authentication token
     * @param {Object|null} userData - User data
     */
    setAuth(status, token = null, userData = null) {
      this.isAuthenticated = status;
      this.token = token;
      this.user = userData;

      // Persist to localStorage
      if (status && token) {
        localStorage.setItem('isAuthenticated', 'true');
        localStorage.setItem('authToken', token);
        localStorage.setItem('user', JSON.stringify(userData));
      } else {
        localStorage.removeItem('isAuthenticated');
        localStorage.removeItem('authToken');
        localStorage.removeItem('user');
      }
    },

    /**
     * Clears the authentication state
     */
    clearAuth() {
      this.setAuth(false);
    }
  });

  // Login page component
  Alpine.data('loginPage', () => ({
    /** @type {string} Username input */
    username: '',

    /** @type {string} Password input */
    password: '',

    /** @type {boolean} Loading state for login request */
    loading: false,

    /** @type {string|null} Error message */
    error: null,

    /**
     * Submits the login form to the API
     * @async
     * @returns {Promise<void>}
     */
    async submitLogin() {
      // Reset error state
      this.error = null;

      // Validate inputs
      if (!this.username || !this.password) {
        this.error = 'Please enter both username and password';
        return;
      }

      // Set loading state
      this.loading = true;

      try {
        const response = await fetch('/api/login', {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json'
          },
          body: JSON.stringify({
            username: this.username,
            password: this.password
          })
        });

        const data = await response.json();

        if (!response.ok) {
          throw new Error(data.message || 'Login failed');
        }

        // Update global auth state
        Alpine.store('auth').setAuth(true, data.token, data.user);

        // Redirect to welcome page
        window.location.href = '/welcome';
      } catch (err) {
        this.error = err.message || 'An unexpected error occurred';
      } finally {
        this.loading = false;
      }
    }
  }));

  // Welcome page component
  Alpine.data('welcomePage', () => ({
    /** @type {boolean} Loading state for logout request */
    loading: false,

    /** @type {string|null} Error message */
    error: null,

    /**
     * Logs out the user by calling the API
     * @async
     * @returns {Promise<void>}
     */
    async logout() {
      // Reset error state
      this.error = null;

      // Set loading state
      this.loading = true;

      try {
        const response = await fetch('/api/logout', {
          method: 'POST',
          headers: {
            'Authorization': `Bearer ${Alpine.store('auth').token}`,
            'Content-Type': 'application/json'
          }
        });

        if (!response.ok) {
          const data = await response.json();
          throw new Error(data.message || 'Logout failed');
        }

        // Clear global auth state
        Alpine.store('auth').clearAuth();

        // Redirect to login page
        window.location.href = '/login';
      } catch (err) {
        this.error = err.message || 'An unexpected error occurred';
        // Even if API fails, clear local state for security
        Alpine.store('auth').clearAuth();
        window.location.href = '/login';
      } finally {
        this.loading = false;
      }
    }
  }));
});
