"""
Pydantic schemas for login-related operations.

This module defines the Pydantic models used for validating and serializing
data for the login API endpoints.
"""

from typing import Optional

from pydantic import BaseModel, Field, StrictStr, validator


class LoginRequest(BaseModel):
    """Request schema for user login.

    Attributes:
        username: The username of the user.
        password: The plain-text password provided by the user.

    Examples:
        >>> data = {"username": "john_doe", "password": "securePassword123"}
        >>> login_request = LoginRequest(**data)
        >>> print(login_request.username)
        john_doe
    """

    username: StrictStr = Field(
        ...,
        min_length=1,
        max_length=150,
        description="The username of the user.",
        example="john_doe"
    )
    password: StrictStr = Field(
        ...,
        min_length=8,
        max_length=128,
        description="The plain-text password of the user.",
        example="securePassword123"
    )

    @validator("username")
    def username_must_not_be_empty(cls, v: str) -> str:
        """Ensure the username is not empty or whitespace only."""
        if not v or not v.strip():
            raise ValueError("Username must not be empty or whitespace only.")
        return v.strip()

    @validator("password")
    def password_must_not_be_empty(cls, v: str) -> str:
        """Ensure the password is not empty or whitespace only."""
        if not v or not v.strip():
            raise ValueError("Password must not be empty or whitespace only.")
        return v

    class Config:
        """Pydantic configuration for LoginRequest."""

        json_schema_extra = {
            "example": {
                "username": "john_doe",
                "password": "securePassword123"
            }
        }


class LoginResponse(BaseModel):
    """Response schema for successful user login.

    Attributes:
        access_token: The JWT access token issued to the user.
        token_type: The type of the token (e.g., "bearer").

    Examples:
        >>> data = {"access_token": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...", "token_type": "bearer"}
        >>> login_response = LoginResponse(**data)
        >>> print(login_response.access_token)
        eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...
    """

    access_token: StrictStr = Field(
        ...,
        description="The JWT access token issued to the user.",
        example="eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9..."
    )
    token_type: StrictStr = Field(
        default="bearer",
        description="The type of the token.",
        example="bearer"
    )

    class Config:
        """Pydantic configuration for LoginResponse."""

        json_schema_extra = {
            "example": {
                "access_token": "eyJhbGciOiJIUzI1NiIsInR5cCI6IkpXVCJ9...",
                "token_type": "bearer"
            }
        }

